// Provision + run the nightly feature-engineering batch.
async function runNightlyBatch(featureSet) {
  // 40 workers for ~3 hours, then torn down
  const fleet = await ec2.runInstances({
    InstanceType: 'm6i.2xlarge',
    MinCount: 40,
    MaxCount: 40,
    MarketType: 'on-demand',
  });

  const out = await processFeatures(featureSet, fleet);

  // persist every intermediate + final artifact
  for (const artifact of out.allArtifacts) {
    await s3.putObject({
      Bucket: 'ml-batch-artifacts',
      Key: artifact.key,
      Body: artifact.body,
      StorageClass: 'STANDARD',
    });
  }

  await ec2.terminateInstances({ InstanceIds: fleet.ids });
  return out.finalArtifact;
}
